-- Faithful copy of the project's legacy practicum schema (for LOCAL TESTS only; never run it against a real database).
-- Tables were reordered so that every referenced table is created before the tables that reference it.
-- The irregular names are preserved on purpose: correInst / correinst / correoinst / correoInst, and
-- "estado " / "numDocAsesor " with a trailing space. The application resolves them at startup (SchemaResolver).
CREATE TABLE programa (idprograma varchar(30) PRIMARY KEY, nombre varchar(100) NOT NULL, facultad varchar(100) NOT NULL);
CREATE TABLE institucion ("nitEntidad" varchar(10) PRIMARY KEY, nombre varchar(150) NOT NULL, direccion varchar(200) NOT NULL, encargado varchar(100) NOT NULL, "correoInstitucion" varchar(100) NOT NULL);
CREATE TABLE tipopractica ("idTipoPractica" varchar(30) PRIMARY KEY, nombre varchar(500) NOT NULL, "numSemestre" integer NOT NULL, "horasRequeridas" integer NOT NULL);
CREATE TABLE asesor_pedagogico ("numDocumento" varchar(30) PRIMARY KEY, "tipoDocumento" varchar(20) NOT NULL, nombre varchar(80) NOT NULL, apellido varchar(80) NOT NULL, "correInst" varchar(100) NOT NULL, contrasena varchar(50) NOT NULL, "googleId" varchar(255) NOT NULL, estado varchar(20) NOT NULL);
CREATE TABLE director ("numDocumento" varchar(30) PRIMARY KEY, "tipoDocumento" varchar(20) NOT NULL, nombre varchar(80) NOT NULL, apellido varchar(80) NOT NULL, correinst varchar(100) NOT NULL, contrasena varchar(50) NOT NULL, estado varchar(20) NOT NULL, "googleId" varchar(255) NOT NULL);
CREATE TABLE estudiante ("numDocumento" varchar(30) PRIMARY KEY, "tipoDocumento" varchar(20) NOT NULL, nombre varchar(80) NOT NULL, apellido varchar(80) NOT NULL, correoinst varchar(100) NOT NULL, contrasena varchar(50) NOT NULL, "googleId" varchar(250) NOT NULL, estado varchar(20) NOT NULL, idprograma varchar(30) NOT NULL REFERENCES programa(idprograma));
CREATE TABLE tutor_academico ("numDocumento" varchar(30) PRIMARY KEY, "tipoDocumento" varchar(20) NOT NULL, nombre varchar(80) NOT NULL, apellido varchar(80) NOT NULL, "correoInst" varchar(100) NOT NULL, contrasena varchar(50) NOT NULL, "googleId" varchar(255) NOT NULL, estado varchar(20) NOT NULL, "Idprograma" varchar(30) NOT NULL REFERENCES programa(idprograma));
CREATE TABLE practica ("idPractica" varchar(30) PRIMARY KEY, "fechaInicio" date NOT NULL, "fechaFinal" date NOT NULL, "notaFinal" numeric(3,2) NOT NULL, "observacionFinal" varchar(1000) NOT NULL, "estado " varchar(30) NOT NULL,
  "idTipoPractica" varchar(30) NOT NULL REFERENCES tipopractica("idTipoPractica"), "numDocEstudiante" varchar(30) NOT NULL REFERENCES estudiante("numDocumento"),
  "numDocTutor" varchar(30) NOT NULL REFERENCES tutor_academico("numDocumento"), "numDocAsesor" varchar(30) NOT NULL REFERENCES asesor_pedagogico("numDocumento"),
  "nitInstitucion" varchar(10) NOT NULL REFERENCES institucion("nitEntidad"));
CREATE TABLE actividad ("idActividad" varchar(30) PRIMARY KEY, nombre varchar(200) NOT NULL, descripcion varchar(4000), "fechaAsignacion" timestamptz NOT NULL, "fechaLimite" timestamptz, "notaObtenida" numeric(3,2), "idPractica" varchar(30) NOT NULL REFERENCES practica("idPractica"));
CREATE TABLE archivosactividad ("idArchivoAct" varchar(30) PRIMARY KEY, "rutaArchivo" varchar(500) NOT NULL, "nombreArchivo" varchar(255) NOT NULL, "tipoMine" varchar(100) NOT NULL, "idActividad" varchar(30) REFERENCES actividad("idActividad"));
CREATE TABLE evidenciaactividad ("idEvidencia" varchar(30) PRIMARY KEY, descripcion varchar(4000), "horasRealizadas" integer NOT NULL, "idActividad" varchar(30) NOT NULL REFERENCES actividad("idActividad"));
CREATE TABLE evidenciaarchivo ("idArchivo" varchar(30) PRIMARY KEY, "rutaArchivo" varchar(500) NOT NULL, "nombreArchivo" varchar(255) NOT NULL, "tipoMine" varchar(100) NOT NULL, "idEvidenciaAct" varchar(30) NOT NULL REFERENCES evidenciaactividad("idEvidencia"));
CREATE TABLE retroalimentacion_a ("idRetroalimentacionA" varchar(30) PRIMARY KEY, comentario varchar(4000) NOT NULL, fecha date NOT NULL, "idEvidencia" varchar(30) NOT NULL REFERENCES evidenciaactividad("idEvidencia"), "numDocAsesor " varchar(30) NOT NULL REFERENCES asesor_pedagogico("numDocumento"));
CREATE TABLE retroalimentacion_t ("idRetroalimentacionT" varchar(30) PRIMARY KEY, comentario varchar(4000) NOT NULL, fecha date NOT NULL, "idEvidencia" varchar(30) NOT NULL REFERENCES evidenciaactividad("idEvidencia"), "numDocTutor" varchar(30) NOT NULL REFERENCES tutor_academico("numDocumento"));
